  "abc154-a": { java: "class Solution {\n    public int[] remainingBalls(String s, String t, int a, int b, String u) {\n        if (u.equals(s)) a--;\n        else b--;\n        return new int[]{a, b};\n    }\n}\n", python: "from typing import List\n\nclass Solution:\n    def remainingBalls(self, s: str, t: str, a: int, b: int, u: str) -> List[int]:\n        if u == s:\n            a -= 1\n        else:\n            b -= 1\n        return [a, b]\n" },
  "abc155-a": { java: "class Solution {\n    public String isPoor(int a, int b, int c) {\n        int eq = (a == b ? 1 : 0) + (b == c ? 1 : 0) + (a == c ? 1 : 0);\n        return eq == 1 ? \"Yes\" : \"No\";\n    }\n}\n", python: "class Solution:\n    def isPoor(self, a: int, b: int, c: int) -> str:\n        eq = (a == b) + (b == c) + (a == c)\n        return \"Yes\" if eq == 1 else \"No\"\n" },
  "abc156-a": { java: "class Solution {\n    public int trueRating(int n, int r) {\n        return n >= 10 ? r : r + 100 * (10 - n);\n    }\n}\n", python: "class Solution:\n    def trueRating(self, n: int, r: int) -> int:\n        return r if n >= 10 else r + 100 * (10 - n)\n" },
  "abc157-a": { java: "class Solution {\n    public int sheetsNeeded(int n) {\n        return (n + 1) / 2;\n    }\n}\n", python: "class Solution:\n    def sheetsNeeded(self, n: int) -> int:\n        return (n + 1) // 2\n" },
  "abc158-a": { java: "class Solution {\n    public String hasBus(String s) {\n        boolean a = s.indexOf('A') != -1;\n        boolean b = s.indexOf('B') != -1;\n        return (a && b) ? \"Yes\" : \"No\";\n    }\n}\n", python: "class Solution:\n    def hasBus(self, s: str) -> str:\n        return \"Yes\" if \"A\" in s and \"B\" in s else \"No\"\n" },
